import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"36、【明夷】 離下坤上","description":"子夏易傳 - 36、【明夷】 離下坤上","frontmatter":{"title":"36、【明夷】 離下坤上","description":"子夏易傳 - 36、【明夷】 離下坤上"},"headers":[],"relativePath":"classics/zixia/038.md","filePath":"classics/zixia/038.md"}'),i={name:"classics/zixia/038.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_36、【明夷】-離下坤上" tabindex="-1">36、【明夷】 離下坤上 <a class="header-anchor" href="#_36、【明夷】-離下坤上" aria-label="Permalink to “36、【明夷】 離下坤上”">​</a></h1><p>卦辭：明夷，利艱貞。</p><p>彖曰：明入地中，明夷。內文明而外柔順，以蒙大難，文王以之利艱貞，晦其明也。內難而能正其志，箕子以之。</p><p>子夏：明入地中，上無以明，天下無所見也。艱以事上，不失於正，利也。故文王內文明而外柔順也。箕子蒙難而能正其志，晦其明者也。</p><p>象曰：明入地中，明夷。君子以涖眾，用晦而明。</p><p>子夏：明入地中，藏其明也。民可使由之，不可使知之，故君子之蒞眾也。外用晦，以使民內保。明以為治。</p><p>初九，明夷，於飛垂其翼，君子於行，三日不食，有攸往。主人有言。</p><p>象曰：君子於行，義不食也。</p><p>子夏：小人賊害之，時有明，則傷矣。初以君子之徳剛而不回，故為時忌之深也。以其無位，猶且逺患，庶以速奔也，故絶其跡，隱其形，三日而不敢食。逃難而遇人，人必疑言矣。害明之深，懼人之見也。君子畏害而速去，其義豈遑食哉。</p><p>六二，明夷，夷於左股，用拯馬壯，吉。</p><p>象曰：六二之吉，順以則也。</p><p>子夏：守中順則無猜者也。而已道不行矣。夷於左股者焉，故與之拯馬而馳逐也。且內明以外順，雖傷左而右存，與時並行不失其吉也。</p><p>九三，明夷於南狩，得其大首，不可疾貞。</p><p>象曰：南狩之志，乃大得也。</p><p>子夏：為文明之主夷終則進也。上六逺其明，雖高而至晦也。應其誅焉。時之得嚮明而南巡狩也。獲其大首耳，其汙俗漸正而已，不可疾也。</p><p>六四，入於左腹，獲明夷之心於出門庭。</p><p>象曰：入於左腹，獲心意也。</p><p>子夏：守以下位，順以上承，自右而入於左腹，獲其心意也。順以避患，止守於分明，其歸自異矣。出於門庭，不逺行也。</p><p>六五，箕子之明夷，利貞。</p><p>象曰：箕子之貞，明不可息也。</p><p>子夏：在難之內，而能保明其中，智以藏之，愚以晦之，得其正而時不能遷也。則明豈息哉。得中之道亡而能有，故箕子當之矣。</p><p>上六，不明晦，初登於天，後入於地。</p><p>象曰：初登於天，照四國也。後入於地，失則也。</p><p>子夏：暗而過中至明夷之極，晦之至也。位高勢，崇登於天也。失道將覆，入於地也。</p>',24)])])}const f=a(i,[["render",r]]);export{m as __pageData,f as default};
